<?php
declare(strict_types=1);
/** Gold calculator helpers. Historical date resolution is now an in-process call. */
require_once dirname(__DIR__, 2) . '/millennium-timezone/millennium-timezone.php';

function getLatest6hSlot(): string { $now=new DateTimeImmutable('now',new DateTimeZone('UTC'));$slots=['00:00:00','06:00:00','12:00:00','18:00:00'];foreach(array_reverse($slots) as $slot){if($now->format('H:i:s') >= $slot)return $now->format('Y-m-d').' '.$slot;}return $now->modify('-1 day')->format('Y-m-d').' 18:00:00'; }
function getLogFile(string $slot): string { $dir=dirname(__DIR__).'/gold_calc/gold_prices';if(!is_dir($dir))@mkdir($dir,0775,true);return $dir.'/gold_cache_'.substr($slot,0,7).'.log'; }
function logExists(string $file,string $slot): bool { return readLogRow($file,$slot)!==null; }
function readLogRow(string $file,string $slot): ?array { if(!is_file($file))return null;$lines=@file($file,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES);if(!$lines)return null;for($i=count($lines)-1;$i>=0;$i--){$row=json_decode($lines[$i],true);if(is_array($row)&&isset($row['timestamp'])&&$row['timestamp']===$slot)return $row;}return null; }
function appendLog(string $file,array $row): void { $dir=dirname($file);if(!is_dir($dir))@mkdir($dir,0775,true);$json=json_encode($row,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if($json!==false)@file_put_contents($file,$json.PHP_EOL,FILE_APPEND|LOCK_EX); }
function getPalmierHistoricalDate(?string $unusedEndpoint=null): DateTime { $result=mtz_get_timezone_payload();if(empty($result['historical_iso']))throw new RuntimeException('Millennium Timezone did not return a historical date.');return new DateTime($result['historical_iso'],new DateTimeZone('UTC')); }
function loadCsvFull(string $file): array { if(!is_readable($file))return [];$lines=file($file,FILE_IGNORE_NEW_LINES);if(!$lines||count($lines)<2)return [];$lines[0]=preg_replace('/^\xEF\xBB\xBF/','',$lines[0]);$rows=array_map('str_getcsv',$lines);$header=array_map(static fn($v)=>strtolower(trim((string)$v)),$rows[0]);$data=[];foreach(array_slice($rows,1) as $row){if(count($row)!==count($header))continue;$entry=array_combine($header,$row);if(is_array($entry)&&isset($entry['date']))$data[trim((string)$entry['date'])]=$entry;}ksort($data);return $data; }
function getRate(array $row): ?float { foreach(['close','open'] as $key){if(isset($row[$key])&&$row[$key]!==''&&is_numeric($row[$key])&&(float)$row[$key]!=0.0)return (float)$row[$key];}return null; }
function findRateMeta(array $data,string $targetDate): ?array { $prev=null;$next=null;foreach($data as $date=>$row){$value=getRate($row);if($value===null)continue;if($date===$targetDate)return ['type'=>'exact','date_used'=>$date,'rate'=>$value,'prev'=>['date'=>$date,'value'=>$value],'next'=>['date'=>$date,'value'=>$value]];if($date<$targetDate)$prev=['date'=>$date,'value'=>$value];if($date>$targetDate){$next=['date'=>$date,'value'=>$value];break;}}if(!$prev||!$next)return null;$t1=strtotime($prev['date'].' UTC');$t2=strtotime($next['date'].' UTC');$t=strtotime($targetDate.' UTC');if($t1===false||$t2===false||$t===false||$t2===$t1)return null;$rate=$prev['value']+($next['value']-$prev['value'])*(($t-$t1)/($t2-$t1));return ['type'=>'interpolated','date_used'=>$targetDate,'rate'=>$rate,'prev'=>$prev,'next'=>$next]; }
function formatPalmierNumber($num): string { $num=number_format((float)$num,4,'.','');$parts=explode('.',$num);$int=strrev(implode("'",str_split(strrev($parts[0]),4)));return $int.'.'.$parts[1]; }
